-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Finanzierungsarten > Kreditfinanzierung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird bei der Kreditfinanzierung von IT-Hardware das Eigentum sofort auf den Betrieb übertragen?', 2, '[{"text": "Ja", "correct": true, "because": "Beim Kreditkauf wird die Hardware gekauft und gehört dem Betrieb"}, {"text": "Nein", "correct": false, "because": "Eigentum wird übertragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Kreditfinanzierung von Servern für einen IT-Betrieb Zinsen gezahlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Kredite beinhalten Zinskosten"}, {"text": "Nein", "correct": false, "because": "Zinsen sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Kreditfinanzierung Liquidität schonen?', 2, '[{"text": "Ja", "correct": true, "because": "Kreditfinanzierung verteilt Kosten über die Zeit"}, {"text": "Nein", "correct": false, "because": "Liquidität wird geschont"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist bei der Kreditfinanzierung von IT-Ausrüstung eine Rückzahlung des Kapitals erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Kredite müssen zurückgezahlt werden"}, {"text": "Nein", "correct": false, "because": "Rückzahlung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb bei der Kreditfinanzierung von Hardware Abschreibungen geltend machen?', 2, '[{"text": "Ja", "correct": true, "because": "Gekaufte Hardware wird als Anlagegut abgeschrieben"}, {"text": "Nein", "correct": false, "because": "Abschreibungen sind möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein wesentliches Merkmal der Kreditfinanzierung für einen IT-Betrieb?', 2, '[{"text": "Fremdkapitalaufnahme mit Zinsen", "correct": true, "because": "Kreditfinanzierung nutzt Fremdkapital"}, {"text": "Sofortige Eigentumsübertragung ohne Rückzahlung", "correct": false, "because": "Rückzahlung ist erforderlich"}, {"text": "Keine Zinskosten", "correct": false, "because": "Zinsen sind typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen einem IT-Betrieb typischerweise bei der Kreditfinanzierung von Servern?', 3, '[{"text": "Anschaffungskosten plus Zinsen", "correct": true, "because": "Kredit deckt Anschaffung, Zinsen entstehen zusätzlich"}, {"text": "Nur monatliche Leasingraten", "correct": false, "because": "Das gilt für Leasing"}, {"text": "Keine zusätzlichen Kosten", "correct": false, "because": "Zinsen sind unvermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb durch die Kreditfinanzierung von Software?', 3, '[{"text": "Verteilung der Kosten über die Zeit", "correct": true, "because": "Kredit ermöglicht Ratenzahlung"}, {"text": "Keine Anfangsinvestition", "correct": false, "because": "Kredit erfordert oft Eigenanteil"}, {"text": "Keine Rückzahlung erforderlich", "correct": false, "because": "Rückzahlung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quelle wird bei der Kreditfinanzierung von IT-Ausrüstung genutzt?', 2, '[{"text": "Fremdkapital", "correct": true, "because": "Kredit ist Fremdfinanzierung"}, {"text": "Eigenkapital", "correct": false, "because": "Eigenkapital ist keine Kreditquelle"}, {"text": "Leasingvertrag", "correct": false, "because": "Das ist eine andere Finanzierungsart"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Kreditfinanzierung von Hardware für einen IT-Betrieb?', 3, '[{"text": "Zinskosten", "correct": true, "because": "Kredite verursachen zusätzliche Kosten"}, {"text": "Keine Eigentumsübertragung", "correct": false, "because": "Eigentum wird übertragen"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kredit bindet an Rückzahlung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Kreditfinanzierung für einen IT-Betrieb?', 4, '[{"text": "Eigentumsübertragung beim Kauf", "correct": true, "because": "Kredit finanziert den Kauf"}, {"text": "Zinskosten", "correct": true, "because": "Fremdkapital verursacht Zinsen"}, {"text": "Keine Rückzahlung", "correct": false, "because": "Rückzahlung ist erforderlich"}, {"text": "Ratenzahlung", "correct": true, "because": "Kredit wird in Raten zurückgezahlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Kreditfinanzierung von IT-Ausrüstung für einen IT-Betrieb?', 3, '[{"text": "Verteilung der Kosten über die Zeit", "correct": true, "because": "Ratenzahlung schont Liquidität"}, {"text": "Eigentum an der Ausrüstung", "correct": true, "because": "Kredit finanziert den Kauf"}, {"text": "Keine Zinskosten", "correct": false, "because": "Zinsen sind unvermeidbar"}, {"text": "Steuerliche Abschreibung", "correct": true, "because": "Gekaufte Ausrüstung wird abgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Kreditfinanzierung von Hardware für einen IT-Betrieb?', 4, '[{"text": "Zinskosten", "correct": true, "because": "Kredit verursacht zusätzliche Kosten"}, {"text": "Rückzahlungsverpflichtung", "correct": true, "because": "Kredit muss zurückgezahlt werden"}, {"text": "Sofortige Eigentumsübertragung", "correct": false, "because": "Das ist ein Vorteil"}, {"text": "Langfristige Kapitalbindung", "correct": true, "because": "Kredit bindet finanziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen bei der Kreditfinanzierung von Softwarelizenzen für einen IT-Betrieb?', 3, '[{"text": "Anschaffungskosten", "correct": true, "because": "Kredit finanziert die Anschaffung"}, {"text": "Zinskosten", "correct": true, "because": "Kredit verursacht Zinsen"}, {"text": "Keine Ratenzahlungen", "correct": false, "because": "Raten sind typisch"}, {"text": "Abschreibungen", "correct": true, "because": "Software wird abgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Kreditfinanzierung von Leasing für einen IT-Betrieb?', 3, '[{"text": "Eigentumsübertragung beim Kauf", "correct": true, "because": "Kredit führt zum Eigentum"}, {"text": "Zinskosten statt Leasingraten", "correct": true, "because": "Kredit hat Zinsen, Leasing Raten"}, {"text": "Keine Rückzahlung erforderlich", "correct": false, "because": "Kredit erfordert Rückzahlung"}, {"text": "Langfristige Nutzung ohne Eigentum", "correct": false, "because": "Das gilt für Leasing"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kreditfinanzierung überträgt das Eigentum an Hardware. b) Kreditfinanzierung hat keine Zinskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kreditfinanzierung verteilt Kosten über die Zeit. b) Kreditfinanzierung erfordert Rückzahlung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Verteilung und Rückzahlung sind Merkmale"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bei Kreditfinanzierung fallen Abschreibungen an. b) Kreditfinanzierung schont keine Liquidität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abschreibungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kreditfinanzierung verursacht Zinskosten. b) Kreditfinanzierung ist ohne Rückzahlung möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zinskosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kreditfinanzierung bindet den Betrieb an Rückzahlungen. b) Kreditfinanzierung hat geringere Anfangskosten als Kauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rückzahlung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

